import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%83%91%E3%82%AA%E7%A2%81.html","title":"パオ碁","lang":"en-US","frontmatter":{},"git":{"createdTime":1755137162000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":58}]},"readingTime":{"minutes":10.15,"words":3046},"filePathRelative":"パオ碁.md"}`),a={name:`パオ碁.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="パオ碁" tabindex="-1"><a class="header-anchor" href="#パオ碁"><span>パオ碁</span></a></h1><ul><li><a href="./囲碁.html">囲碁</a></li><li><a href="./自作アプリ.html">自作アプリ</a></li></ul><h2 id="url" tabindex="-1"><a class="header-anchor" href="#url"><span>url</span></a></h2><ul><li><a href="https://play.google.com/store/apps/details?id=io.github.karino2.paoogo" target="_blank" rel="noopener noreferrer">Google Play: パオ碁</a></li><li><a href="https://github.com/karino2/PaooGo" target="_blank" rel="noopener noreferrer">karino2/PaooGo: Go app for android, fork from gobandroid.</a><ul><li>以下のエンジンもcpp下に置く必要がある（今のところシンボリックリンクにしてる、将来submoduleにする予定）</li><li><a href="https://github.com/karino2/GnuGo2Fork" target="_blank" rel="noopener noreferrer">karino2/GnuGo2Fork</a></li><li><a href="https://github.com/karino2/Ray/tree/android_fork" target="_blank" rel="noopener noreferrer">karino2/Ray android_fork</a></li><li><a href="https://github.com/karino2/LibertyFork" target="_blank" rel="noopener noreferrer">karino2/LibertyFork</a></li><li><a href="https://github.com/karino2/KataGo" target="_blank" rel="noopener noreferrer">karino2/KataGo: android_fork</a></li><li><a href="https://github.com/karino2/AmigoGtpFork" target="_blank" rel="noopener noreferrer">karino2/AmigoGtpFork</a></li><li><a href="https://github.com/karino2/gnugo_fork" target="_blank" rel="noopener noreferrer">karino2/gnugo_fork</a></li></ul></li><li><a href="https://github.com/karino2/PaooGo/tree/a7b46c72887fa1d27a7d60fb4fa381bd831c94d7" target="_blank" rel="noopener noreferrer">karino2/PaooGoのfork時のコミット</a> コード参考にする時にちょくちょく見たくなるので</li></ul><h2 id="コンセプト" tabindex="-1"><a class="header-anchor" href="#コンセプト"><span>コンセプト</span></a></h2><p>ぴよ将棋のようなアプリの囲碁版が欲しい。</p><ul><li>セットアップ無し、広告無しですぐに打ち始められる</li><li>弱いエンジンと戦える</li><li>ヒント、検討が出来る</li><li>カスタマイズ性や強いエンジンを使える、などの機能はサポートしない</li><li>ネットワークパミッションやファイルパミッションは無しにしたい</li></ul><p>こんな感じのものを作りたい。 だいたい囲碁であそぼ！の修行のlv 3くらいをやっている人を対象にしたようなアプリで、 初段くらいまで使える、というのを目指したい（初段がどのくらい強いのか知らないが）。</p><h2 id="開発方針" tabindex="-1"><a class="header-anchor" href="#開発方針"><span>開発方針</span></a></h2><ul><li>gobandroidをforkして開発する</li><li>対局用の碁エンジンとしては AmigoGtp, liberty, gnugo2.6, gnugo3.8の4つとする</li><li>解析用にはKataGo b6を使う</li><li>囲碁のルール等はgnugo3.8を使う</li><li>囲碁エンジンはapkにすべて含めて、設定無しでそのまま使える状態にする</li></ul><p>対局用のエンジンは、間を埋めるような復数エンジンの混ぜ合わせはやる必要がありそう。</p><h2 id="とりあえずの目標" tabindex="-1"><a class="header-anchor" href="#とりあえずの目標"><span>とりあえずの目標</span></a></h2><p>先を考えすぎるとやる気がわかないので、直近の目標だけを考えてみる。</p><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> 棋譜の読み書き</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> 死活判定をGnuGo 3.8を使うように変更</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> 9路の適当な布石対応</label></li></ul><h2 id="開発メモ" tabindex="-1"><a class="header-anchor" href="#開発メモ"><span>開発メモ</span></a></h2><p>ここまでの作業のメモを以下に書く。</p><h3 id="gobandroidいじり" tabindex="-1"><a class="header-anchor" href="#gobandroidいじり"><span>gobandroidいじり</span></a></h3><ul><li>guavaとかをdependenciesに追加</li><li>ライブラリを適当にアップデート</li><li>AndoidManifests.xmlにGnuGoのサービスのqueryを追加</li></ul><p>このくらいで動いた。検討出来ないのかな？</p><h3 id="katagoのndkでのビルド" tabindex="-1"><a class="header-anchor" href="#katagoのndkでのビルド"><span>katagoのNDKでのビルド</span></a></h3><p>NDKでビルドしてみる。大変かしら？</p><p>まずは公式をgit clone。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ git clone https://github.com/lightvector/KataGo.git</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>そしてndkのビルドをする。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ export ANDROID_NDK_HOME=~/Library/Android/sdk/ndk/25.2.9519653</span>
<span class="line">$ cd cpp</span>
<span class="line">$ mkdir build</span>
<span class="line">$ cmake . -B build -DCMAKE_TOOLCHAIN_FILE=\${ANDROID_NDK_HOME}/build/cmake/android.toolchain.cmake -DCMAKE_BUILD_TYPE=Release -DANDROID_NATIVE_API_LEVEL=33 -DANDROID_NDK=\${ANDROID_NDK_HOME} -DANDROID_ABI=armeabi-v7a -DUSE_BACKEND=EIGEN</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Eigenが見つからんと言われた。 Eigenはヘッダだけinclude出来る場所に置けば良さそうだな。</p><p>ダウンロードはここか？</p><p><a href="http://eigen.tuxfamily.org/index.php?title=Main_Page#Download" target="_blank" rel="noopener noreferrer">Eigen</a></p><p>なんかhttpsじゃないんだが…</p><p>とりあえず3.4.0をダウンロードする。 そしてcpp/external下に置く。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">cpp $ cd external</span>
<span class="line">cpp/external $ tar xzvf eigen-3.4.0.tar.gz</span>
<span class="line"># cpp/external/eigen-3.4.0が出来る</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>次にこれをCMakeLists.txtに加えればいいのか？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">include_directories(external/eigen-3.4.0)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>そしてfind_packageで怒られるのでコメントアウトしておく。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">#    find_package(Eigen3 REQUIRED)</span>
<span class="line">#    include_directories(SYSTEM \${EIGEN3_INCLUDE_DIRS})</span>
<span class="line"> #   message(STATUS &quot;Found Eigen3 at \${EIGEN3_INCLUDE_DIRS}&quot;)</span>
<span class="line"> message(STATUS &quot;Skip eigen3 package find&quot;)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>なんかlibzipがないからself playはzipの結果書き出しが出来ないから出来ないよ、とか言われるがしないのでいいだろう。</p><p>ではビルド。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ cd build</span>
<span class="line">$ make -j 16</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>なんか以下のエラーが出た。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">KataGo/cpp/core/sha2.cpp:205:2: error: Define BYTE_ORDER to be equal to either LITTLE_ENDIAN or BIG_ENDIAN</span>
<span class="line">#error Define BYTE_ORDER to be equal to either LITTLE_ENDIAN or BIG_ENDIAN</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>まぁどうせlittle endianでいいんだが、CMakeだけにしておきたいな。という事でさっきのmessageの下に以下を追加。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">    message(STATUS &quot;Skip eigen3 package find&quot;)</span>
<span class="line">    # NDK</span>
<span class="line">    target_compile_definitions(katago PRIVATE BYTE_ORDER=1234)</span>
<span class="line">    target_compile_definitions(katago PRIVATE LITTLE_ENDIAN=1234)</span>
<span class="line">    target_compile_definitions(katago PRIVATE BIG_ENDIAN=4321)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>これでビルド出来た。 ビルドした結果はexeになってしまっている気がするな。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">build $ file katago</span>
<span class="line">katago: ELF 32-bit LSB pie executable, ARM, EABI5 version 1 (SYSV), dynamically linked, interpreter /system/bin/linker, BuildID[sha1]=a209a1e7210ea98f1bebe78b6122bb0621b09b5d, with debug_info, not stripped</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>adb shellで動かしてみるか？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">build $ export PATH=$PATH:~/Library/Android/sdk/platform-tools</span>
<span class="line">build $ adb push katago /sdcard/temp/katago</span>
<span class="line">build $ adb shell</span>
<span class="line">penang:/ $ cd /sdcard/temp</span>
<span class="line">penang:/sdcard/temp $ ./katago</span>
<span class="line">/system/bin/sh: ./katago: can&#39;t execute: Permission denied</span>
<span class="line">126|penang:/sdcard/temp $ chmod +x katago</span>
<span class="line">penang:/sdcard/temp $ ./katago</span>
<span class="line">/system/bin/sh: ./katago: can&#39;t execute: Permission denied</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>なんで？ sdcard下は実行出来ないんだった。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ adb shell</span>
<span class="line">/ % cd /data/local/tmp</span>
<span class="line">/data/local/tmp % cp /sdcard/temp/katago ./</span>
<span class="line">/data/local/tmp % chmod 755 katago</span>
<span class="line">/data/local/tmp % ./katago</span>
<span class="line">penang:/data/local/tmp $ ./katago</span>
<span class="line"></span>
<span class="line">Usage: ./katago SUBCOMMAND</span>
<span class="line"></span>
<span class="line">---Common subcommands------------------</span>
<span class="line"></span>
<span class="line">gtp : Runs GTP engine that can be plugged into any standard Go GUI for play/analysis.</span>
<span class="line">benchmark : Test speed with different numbers of search threads.</span>
<span class="line">genconfig : User-friendly interface to generate a config with rules and automatic performance tuning.</span>
<span class="line"># 以下略</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>おぉ、動いた！</p><p>モデルとcfgを動かしてgtpモードで動かしてみよう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Mac$ adb push g170e-b20c256x2-s5303129600-d1228401921.bin.gz /sdcard/temp/</span>
<span class="line">g170e-b20c256x2-s5303129600-d1228401921.bin.gz: 1 file pushed, 0 skipped. 37.4 MB/s (87358203 bytes in 2.229s)</span>
<span class="line">Mac$ adb push ./cpp/configs/gtp_example.cfg /sdcard/temp/</span>
<span class="line">./cpp/configs/gtp_example.cfg: 1 file pushed, 0 skipped. 67.7 MB/s (32457 bytes in 0.000s)</span>
<span class="line">Mac$ adb shell</span>
<span class="line">penang:/ $ cd /data/local/tmp</span>
<span class="line">penang:/data/local/tmp $ cp /sdcard/temp/g17* ./</span>
<span class="line">penang:/data/local/tmp $ cp /sdcard/temp/gtp* ./</span>
<span class="line">penang:/data/local/tmp $ ./katago gtp -model g170e-b20c256x2-s5303129600-d1228401921.bin.gz -config gtp_example.cfg</span>
<span class="line">KataGo v1.16.3</span>
<span class="line">Using TrompTaylor rules initially, unless GTP/GUI overrides this</span>
<span class="line">Initializing board with boardXSize 19 boardYSize 19</span>
<span class="line">Loaded config gtp_example.cfg</span>
<span class="line">Loaded model g170e-b20c256x2-s5303129600-d1228401921.bin.gz</span>
<span class="line">Model name: g170-b20c256x2-s5303129600-d1228401921</span>
<span class="line">GTP ready, beginning main protocol loop</span>
<span class="line">protocol_version</span>
<span class="line">= 2</span>
<span class="line"></span>
<span class="line">boardsize 9</span>
<span class="line">Initializing board with boardXSize 9 boardYSize 9</span>
<span class="line">=</span>
<span class="line"></span>
<span class="line">komi 6.5</span>
<span class="line">=</span>
<span class="line"></span>
<span class="line">play b D4</span>
<span class="line">=</span>
<span class="line"></span>
<span class="line">genmove w</span>
<span class="line">= D6</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>おー、動いた！でもgenmoveは1分以上掛かってるな。</p><p>maxVisitsを10にすると5秒くらいに。こんなもんでいいかも。</p><p>とりあえずここまでを公開。</p><p><a href="https://github.com/karino2/KataGo/tree/android_fork" target="_blank" rel="noopener noreferrer">karino2/KataGo at android_fork</a></p><h3 id="gobandroidのgnugoプラグインのコードを読む" tabindex="-1"><a class="header-anchor" href="#gobandroidのgnugoプラグインのコードを読む"><span>gobandroidのGnuGoプラグインのコードを読む</span></a></h3><p>サービスにしているのは知っているが、exeを呼んでるのかsoをJNIで呼んでるのかとかを調べていきたい。</p><p>以下か。</p><p><a href="https://github.com/ligi/gobandroid-ai-gnugo" target="_blank" rel="noopener noreferrer">ligi/gobandroid-ai-gnugo: this is a ai service for gnugo</a></p><p>Android.mkは自分で書いていて、soになっている。</p><p><code>src/main/jni/project/gnugo-3.8/interface/java_bridge.c</code> にJNIの実装があって、以下の２つだけを実装している。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">void</span>
<span class="line">Java_org_ligi_gobandroidhd_ai_gnugo_GnuGoConnection_initGTP (</span>
<span class="line">	JNIEnv*	env,</span>
<span class="line">	jclass clasz,</span>
<span class="line">	jfloat memory</span>
<span class="line">	)</span>
<span class="line">{</span>
<span class="line">	init_gtp (memory);</span>
<span class="line">}</span>
<span class="line"></span>
<span class="line">jstring</span>
<span class="line">Java_org_ligi_gobandroidhd_ai_gnugo_GnuGoConnection_playGTP (</span>
<span class="line">	JNIEnv*	env,</span>
<span class="line">	jclass clasz,</span>
<span class="line">	jstring input</span>
<span class="line">	)</span>
<span class="line">{</span>
<span class="line">	char *cinput = (char*)(*env)-&gt;GetStringUTFChars (env, input, NULL);</span>
<span class="line">	strcpy (gtp_input_line, cinput);</span>
<span class="line">	gtp_output_line[0] = &#39;\\0&#39;;</span>
<span class="line">	play_gtp ();</span>
<span class="line">	(*env)-&gt;ReleaseStringUTFChars (env, input, cinput);</span>
<span class="line">	return (*env)-&gt;NewStringUTF (env, gtp_output_line);</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>これくらいならすぐ作れそうだな。</p><h3 id="メモ" tabindex="-1"><a class="header-anchor" href="#メモ"><span>メモ</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">./katago gtp -config gtp_human20k.cfg -model your_favorite_normal_model_for_katago.bin.gz -human-model b18c384nbt-humanv0.bin.gz</span>
<span class="line"></span>
<span class="line">./katago gtp -config gtp_human20k.cfg -model b18c384nbt-humanv0.bin.gz -human-model b18c384nbt-humanv0.bin.gz</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>weak2 s10014464弱すぎ、weak3 s14649344 強すぎ</p><h3 id="弱い囲碁エンジンを求めて" tabindex="-1"><a class="header-anchor" href="#弱い囲碁エンジンを求めて"><span>弱い囲碁エンジンを求めて</span></a></h3><p><a href="https://cgit.git.savannah.gnu.org/cgit/gnugo.git" target="_blank" rel="noopener noreferrer">gnugo.git - gnugo</a></p><p>gnugoをlevel 0で触っているが、序盤が弱くて終盤が強すぎる。 ただgnugoは終盤が人間っぽいというかちゃんとパスしてくれる。</p><p>michiをN_SIMSを減らして見たが100だと動かなくて400だと強すぎる。</p><p>調べていたらこんなサブレを見つけた。</p><p><a href="https://www.reddit.com/r/baduk/comments/fq0i33/whats_the_best_way_to_bring_an_ai_down_to_my_rank/" target="_blank" rel="noopener noreferrer">What’s the best way to bring an AI down to my rank? : r/baduk</a></p><p>zen7が弱いらしい。</p><p>何それ？とググっていたら以下のレーティングを見つける。</p><p><a href="https://github.com/breakwa11/GoAIRatings/tree/master" target="_blank" rel="noopener noreferrer">breakwa11/GoAIRatings: Estimate Go AI ratings by real games</a></p><p>Amigoってのも弱いな、と調べて以下にいきつく。</p><p><a href="https://sourceforge.net/projects/amigogtp/" target="_blank" rel="noopener noreferrer">AmiGoGtp download - SourceForge.net</a></p><p>ちょっと手を入れたらビルドが通った。少し戦うと弱さは自分と同じくらいで悪くない。 ただすごく弱い時とすごく強い時がある感じで、取り合いが強すぎて序盤が弱すぎる感じか。 まぁこれは割と戦える。</p><p>zen7は売り物っぽい。</p><p>go169というのもあったので調べてみるが、ソースは見つからない。けれど、その前身のGo81はソースがあった。</p><p><a href="https://users.ics.aalto.fi/praiko/go81/" target="_blank" rel="noopener noreferrer">Go81 for Palm by Tapani Raiko</a></p><p>展開してみるとpalm用という感じだが少しいじればビルドは出来そう。Go169はAmiGoより強そうだがいい勝負っぽい。 Go81がいい感じに弱い可能性もあるが、強さが分からない段階でビルドしてみるのもなぁ。</p><p>とりあえず</p><ul><li>初心者用はAmiGo</li><li>スコアとかの基本的なライブラリとしてはGnuGo</li><li>分析はkatago b6の最強モデル</li></ul><p>の３つがあればどうにかなるかな？</p><p>gnugoの2.6はconfigureしたら途中でこける。まぁそれはそうか。</p><p>少しいじってビルドを通した。gtpが無い。</p><p>デフォルトではちょっと勝てないくらい強いが <code>-D 4</code> を指定したら勝てた。</p><ul><li><a href="http://www.yss-aya.com/cgos/9x9/bayes.html" target="_blank" rel="noopener noreferrer">9x9 All Time Ranks</a> ランク。いい囲碁エンジンないかな〜。</li><li><a href="http://ricoh51.free.fr/go/engineeng.htm" target="_blank" rel="noopener noreferrer">Download free go engines</a> 古い囲碁エンジンの名前がわかる。だいたいリンク切れだが。</li></ul><p>libertyが意外と弱そうなので少し調べてみる。</p><ul><li><a href="https://lists.gnu.org/archive/html/gnugo-devel/2005-08/msg00036.html" target="_blank" rel="noopener noreferrer">gnugo-devel Liberty 1.0 and GNU Go 2.0 GTP modifications.</a></li><li><a href="https://sourceforge.net/projects/londerings/" target="_blank" rel="noopener noreferrer">Londerings download - SourceForge.net</a></li></ul><p>internet archiveで古い記事を見ているとlibertyはKGSで24Kとの事。GnuGo 2.6は17kなので結構差があるかも。 少しいじってGTPで動くようにした。</p><p><a href="https://github.com/karino2/LibertyFork" target="_blank" rel="noopener noreferrer">karino2/LibertyFork: Liberty fork for imlement more GTP commands.</a></p><p>以下にこの辺のエンジンのKGSの棋力が載っている。</p><p><a href="https://note.com/gouponline/n/n8d98d6ca422e" target="_blank" rel="noopener noreferrer">かつて存在した「初心者向け囲碁対局サイトGo-Up!」について（墓標）｜Go-Up</a></p><h3 id="gtpエンジン同士を戦わせる" tabindex="-1"><a class="header-anchor" href="#gtpエンジン同士を戦わせる"><span>GTPエンジン同士を戦わせる</span></a></h3><p><a href="./囲碁エンジン評価.html">囲碁エンジン評価</a>に移動。</p><h3 id="続-gobandroidのgnugoプラグインのコードを読む" tabindex="-1"><a class="header-anchor" href="#続-gobandroidのgnugoプラグインのコードを読む"><span>続： gobandroidのGnuGoプラグインのコードを読む</span></a></h3><p>gnugoのコードベースの理解が進んだのでもう一度gobandroid用のエンジンのサービスのコードを軽く眺める。 どうも口としてはplayGtpというものだけにして、文字列を送る感じにしているようだ。 で、play_gtpと同じようなものを少し雑にいじってグローバル変数に入れた文字列をstdinであるかのように偽造している。</p><p>これでもまぁやりたいことは出来るのだろうけれど、囲碁のライブラリとしてGnuGoを使おうと思うならもうちょっとJNIの口を頑張って整備してもいい気はする。</p><p>gtpのコマンドはバラしてJNIのメソッドにしたいところ。</p><h3 id="レポジトリ作成、開発開始-2025-08-30-土" tabindex="-1"><a class="header-anchor" href="#レポジトリ作成、開発開始-2025-08-30-土"><span>レポジトリ作成、開発開始 2025-08-30 (土)</span></a></h3><p>名前をパオ碁に決定して正式にfork。applicationIdなどを変更して開発開始。</p><p>とりあえずgnugo2.6をapkに含めて動かす、というのを最初の目標にしよう。 方針としてはgnugo2.6はレポジトリは別にしたままにして、しばらくはシンボリックリンクでsrc下に置く感じにしたい。 時期が来たらsubmoduleにするかも。</p><p>とりあえずAndroid.mkとApplication.mkを書こうと思い、参考にするサンプルでも探そうとすると、なんかみんなCMakeLists.txt使ってるな。 最近はそういうものなの？と公式ページを見るとCMakeLists.txtを使うとの事。</p><p><a href="https://developer.android.com/ndk/guides" target="_blank" rel="noopener noreferrer">Get started with the NDK \xA0-\xA0 Android NDK \xA0-\xA0 Android Developers</a></p><p>うーむ、Android用のためだけにCMakeLists.txtを用意してそれ以外はcongigureとMakefile.inを使い続けるってややこしいので嫌なんだが、まぁいいか。</p><p>とりあえずGnuGo2のsoが出来た。インターフェースはまだinitしか書いてないが。 リンクができればかなり前身ではある。AmigoGtpやGnuGo3やKataGoでも同じ事をやらないといけないので先は長いが。</p><p>先を考えるとやる気が失せるので、GnuGo2と戦えるようにするまでだけを考えよう。 そう思えばあとはインターフェースを書いてGnuGo3を呼んでいるところを差し替えるだけなのであと一歩だ。</p><p>gnugo2と戦えるところまで来た。なんかundoすると馬鹿になったり（clearboardして最初からplayで動かしているつもり）こっちがパスすると終わってしまったりと細々とおかしいが。</p><h3 id="undo周りのバグを修正-2025-08-31-日" tabindex="-1"><a class="header-anchor" href="#undo周りのバグを修正-2025-08-31-日"><span>undo周りのバグを修正 2025-08-31 (日)</span></a></h3><p>いつまでもパスしないで延々と自分の地を削り続けるという謎の挙動の原因を追って、undo周りのバグを潰す。 その過程で調査周りのコードが充実してきたり怪しいところが無くなったりして、だいぶ普通に動くようになってきた。</p><p>次はUIを変えてGnuGo2.6との対局をメインとする遷移にしたいな。</p><p>KataGoのコードを少し読んでいる。よく書けているな。 main.cppと同じことをしつつgtp.cppをバラしたようなAPIを作れば良さそう。 IOはかなり綺麗に切れているのでやれば出来そうに思える。 むしろこれだけ綺麗に切ってあるのにCMakeLists.txtにsoが無いのは驚きだな。</p><h3 id="タイトル画面を作り、遷移を普通のゲームっぽくする-2025-09-04-木" tabindex="-1"><a class="header-anchor" href="#タイトル画面を作り、遷移を普通のゲームっぽくする-2025-09-04-木"><span>タイトル画面を作り、遷移を普通のゲームっぽくする 2025-09-04 (木)</span></a></h3><p>起動して普通にゲームをやる時の遷移になるようにタイトル画面を作り直し。 とりあえず初めての人でも使い方が分からない、という感じでは無くなったかな。 いらないのを全部削ってアイコンを変えたらapkをどっかにおいてアナウンスしてみてもいいかもしれない。</p><h3 id="解析もrayでいいかもしれない-2025-09-06-土" tabindex="-1"><a class="header-anchor" href="#解析もrayでいいかもしれない-2025-09-06-土"><span>解析もrayでいいかもしれない 2025-09-06 (土)</span></a></h3><p>rayのlz-analyzeをつけてgnugoと打ってみたが、割と十分つよいな。</p><p><a href="http://kashi.zenno.info/~kashi/bot/" target="_blank" rel="noopener noreferrer">Bot for iGo</a> によると2段くらい、との事。とりあえずこれでいいか。</p><h3 id="rayをjniで使えるようにする-2025-09-11-木" tabindex="-1"><a class="header-anchor" href="#rayをjniで使えるようにする-2025-09-11-木"><span>Rayをjniで使えるようにする 2025-09-11 (木)</span></a></h3><p>とりあえずビルドをするところから。適当にCMakeLists.txtを書いて、</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ export ANDROID_NDK_HOME=~/Library/Android/sdk/ndk/27.0.12077973</span>
<span class="line">$ mkdir build</span>
<span class="line">$ cmake . -B build -DCMAKE_TOOLCHAIN_FILE=\${ANDROID_NDK_HOME}/build/cmake/android.toolchain.cmake -DCMAKE_BUILD_TYPE=Release -DANDROID_NATIVE_API_LEVEL=33 -DANDROID_NDK=\${ANDROID_NDK_HOME} -DANDROID_ABI=armeabi-v7a</span>
<span class="line">$ cd build</span>
<span class="line">$ make -j 16</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>おや、一発で通る。よしよし。では次にjniを書いていこう。</p><h3 id="sim-paramsとuct-paramsを調べる" tabindex="-1"><a class="header-anchor" href="#sim-paramsとuct-paramsを調べる"><span>sim_paramsとuct_paramsを調べる</span></a></h3><p>ファイルから読んでいるが、Android的にはJavaで読んで渡したいよなぁ。 とりあえず読んでいるところを調べる事から。</p><p>uct_paramsはUctRating.cppのInputUCTParameterで読んでいる。 fm_tという構造体の配列を初期化する、というのと、hashとhash_indexを初期化する、という構成になっているな。</p><p>fm_tはdouble一つとdouble 5個の配列で出来ているのでようするにdouble 6個だな。 小さい配列はJava側でdoubleの配列を初期化して渡して、大きい配列はC++側のポインタを変えさせてJava側で初期化するか。</p><p>Hashもunsigned long longとintなのでjintを3みつとして初期化していけばいいか？</p><p>なんとなくuct_paramsの初期化の関数は書いた（呼ぶのはまだ）。</p><p>sim_paramsはRating.cppのLoadFeatureParametersだな。</p><p>中身を見るとpo_md2以外は大してデカくないな。po_pat3もたかだか64Kだし、全部まとめて入れてしまう、でいいか。 う、uct_paramsもそうした方が良かったな。</p><p>zipをassetsに加えたらcloseEntryが遅くてうーん、と悩んでいたが、 そもそもzipではなく素のファイルでいいんじゃない？apkは圧縮されるんだから、と言われて、そういえばそうだなと思って修正。</p><p>uct_paramsのうち、小さい奴は一通り終わり。 あとはJava側で初期化する奴とsimだな。</p><h3 id="rayのandroidでの動作に成功-2025-09-12-金" tabindex="-1"><a class="header-anchor" href="#rayのandroidでの動作に成功-2025-09-12-金"><span>RayのAndroidでの動作に成功 2025-09-12 (金)</span></a></h3><p>uctの初期化終了</p><p>MD3.txtなどは思ったよりもtoDoubleが時間が掛かるので、諦めてpythonでバイナリフォーマットを作る方針に変更。 まぁまぁ大掛かりになってきたが、無事uct_paramsは終わる。</p><p>だいぶいろいろ整備も進んだのでsimもそう大変ではなかろう。</p><p>結局1日かけて、動くところまでは出来た。なんかたまにフリーズするのでバグってそうだが。</p><h3 id="いらないものをいろいろ削除、libertyを追加-2025-09-13-土" tabindex="-1"><a class="header-anchor" href="#いらないものをいろいろ削除、libertyを追加-2025-09-13-土"><span>いらないものをいろいろ削除、libertyを追加 2025-09-13 (土)</span></a></h3><p>ヒントや検討を作っていくにあたり、既に動かなくなっているいろいろなActivityなどが邪魔なので簡単に削除出来るものは一通り削除しておく。 だいぶ見通しは良くなった。</p><p>そしてGnuGo 2.6はdepth 4固定にしたら全く勝てなくなってしまった。うーん、ちょっと強すぎるな、こいつ。 やはりAmiGoと混ぜて適当な強さを作る方法を探求する必要がありそうだ。</p><p><a href="https://go-up.heartful-space.com/" target="_blank" rel="noopener noreferrer">Go-Up! - 初心者向け 囲碁対局Webアプリ</a> をやっていたら、Libertyがいい感じの弱さだったので試しにビルドしたりGTPインターフェースをもう少し追加したりしてSabakiで遊んでいたところ、 このくらいならすぐ組み込めそう、という事でパオ碁に組み込んでみた。</p><p>ただしばらく打っているとクセになれてしまって勝ち方を覚えてしまった。やはりGnuGo 2.6の方がそこまで単純では無いよな。</p><h3 id="ヒントの実装-2025-09-17-水" tabindex="-1"><a class="header-anchor" href="#ヒントの実装-2025-09-17-水"><span>ヒントの実装 2025-09-17 (水)</span></a></h3><p>とりあえずanalyzeを2秒やって一番上の結果を使う感じのヒントを実装する。 どうも盤面のsyncがうまく行ってないようで、途中から既に打ってある座標を返す。</p><p>とりあえずバグは直すが、大枠は出来たかな。</p><p>stringstreamのクリアを忘れていただけだった。そしてclearをしてもクリアされなくてなんでかな？といつものハマりをやる（strを使え、とのgemini先生の教えに従う）。</p><p>無事ヒントが動くようになった。</p><p>初期化が3秒位かかるのがちょっときになるので調べていると、どうもgetDoubleが遅い。 別にdoubleにする必要も無いので、そのままバイト列を流してみるかなぁ。</p><h3 id="意外と日本ルールと中国ルールの違いがある-2025-09-18-木" tabindex="-1"><a class="header-anchor" href="#意外と日本ルールと中国ルールの違いがある-2025-09-18-木"><span>意外と日本ルールと中国ルールの違いがある 2025-09-18 (木)</span></a></h3><p>バイト列を流してだいぶ初期化も早くなった。</p><p>どうもRayが毎回半目差で負けるのは、中国ルールだと勝っているからっぽい。確かに変な手入れするので中国ルールなんだろうな、とは思っていたが。 少し調べたが日本ルールにする方法は無いっぽい。</p><p>うーん、自分は日本ルールでやりたいんだよなぁ。というかいろんなルールどころか日本ルールでもまだ良く分かってないので、他のルールの事なんて興味無い。</p><p>Sabakiでkatagoに日本ルールにして試すと期待通りに動いているので、やはりKataGoを入れるかなぁ。</p><h3 id="katagoのjni作り-2025-09-20-土" tabindex="-1"><a class="header-anchor" href="#katagoのjni作り-2025-09-20-土"><span>KataGoのJNI作り 2025-09-20 (土)</span></a></h3><p>KataGoを使ってみよう、という事で本格的にJNIを書き始める。 まずは簡単に外せそうなものを外してsoを作る事から。ちょっと書いたらsoは出来た。</p><p>GTPEngineを流用する感じで初期化周りを持ってきている。 そのままでは関数から出ない前提になっているので直す必要がちょくちょくあるが、逆にこれが出来たらほぼ完成だな、これ。</p><p>一応Analyzeの手前くらいまでは書いて、analyzeのコードを理解したくらいまで進めてガス欠。 あと一歩だが一日では終わらないかな。</p><p>散歩行ったあとに気が向いたので動かす所までやるとあっさり動く。 そして超強い。1sec考えるrayでも全部石取ってしまう。無敵。</p><p>残りの作業をこの辺で考えたい。</p><ul><li>検討機能を入れたい</li><li>エンジンを増やしたい</li><li>間のレベルのエンジンを増やしたい</li></ul><p>ここまで出来たら完成だな。とりあえず検討機能かな〜。</p><h3 id="検討機能作り始め-2025-09-25-木" tabindex="-1"><a class="header-anchor" href="#検討機能作り始め-2025-09-25-木"><span>検討機能作り始め 2025-09-25 (木)</span></a></h3><p>EditGameActivityを参考にReviewActivityを作成開始。</p><p>とりあえずGameを進めたり戻したり、という機能はすでに実装済みだったのを整理していい感じになる。 ただいろいろ出来ていないのでちょっと実装しなきゃいけない事を整理するか。</p><ul><li>variationに数字をつける</li><li>本手順に戻る、を実装</li></ul><p>コードベースの理解を深めつつなんとなく実装が出来た。 次は解析関連の機能だな。</p><h3 id="解析の機能を実装-2025-09-27-土" tabindex="-1"><a class="header-anchor" href="#解析の機能を実装-2025-09-27-土"><span>解析の機能を実装 2025-09-27 (土)</span></a></h3><p>夜になんとなくパオ碁の実装でも進める気分になったので、軽く実装してみたら無事できる。だいぶ完成度が上がってきたな。</p><p>なんか文字が見づらいのがいまいちだな。Sabakiだと色をアルファで少し薄めに表示して、その上から白で文字を書いているなぁ。</p><h3 id="検討からの再開を実装-2025-10-02-木" tabindex="-1"><a class="header-anchor" href="#検討からの再開を実装-2025-10-02-木"><span>検討からの再開を実装 2025-10-02 (木)</span></a></h3><p>検討から再開出来るように出来た。これで負けそうになったら検討でいろいろ調べてから再開出来るように。</p><p>あとはCPUを増やして、使えないメニューを一旦潰せば人に試してもらえるかな。</p><p>次はAmigoGtpをつなげてみよう＞つなげた</p><p>なんかlibertyとどっちが強いか微妙だな、AmigoGtp。まぁいいや。</p><h3 id="gnugo3-8もつなげる、rayを外す-2025-10-05-日" tabindex="-1"><a class="header-anchor" href="#gnugo3-8もつなげる、rayを外す-2025-10-05-日"><span>GnuGo3.8もつなげる、Rayを外す 2025-10-05 (日)</span></a></h3><p>GnuGo 3.8をつなげたら十分強かったので、もうこれでいいや、という事でRayを外す。 コードは残してparamsだけassetsの外に移動する。</p><p>GnuGo 3.8は序盤から明らかに勝てない感じだな。GnuGo 2.6は序盤はそんな強くもない印象だが。</p><p>現時点でのapkのサイズは以下。</p><ul><li>Ray無し 67.1MB</li><li>Rayあり 120.4MB</li></ul><p>無しにしよう。</p><p>アイコンも描いてあとはUI周りの整備をしたらリリースは出来そうだな。</p><h3 id="aboutをつける-2025-10-09-木" tabindex="-1"><a class="header-anchor" href="#aboutをつける-2025-10-09-木"><span>Aboutをつける 2025-10-09 (木)</span></a></h3><p>謝辞を復活させてリンクが切れてないものだけにして、エンジンのリンクなども足す。まぁ動いてそう。</p><h3 id="google-playにリリース作業-2025-10-10-金" tabindex="-1"><a class="header-anchor" href="#google-playにリリース作業-2025-10-10-金"><span>Google Playにリリース作業 2025-10-10 (金)</span></a></h3><p>スクリーンショットを足そうととっていたら、ついでにGoogle Playにもリリースするか、という気分になりリリース作業。 Closed Testとかがあってリリースまでの手順がわかりにくくなっているなぁ。</p><p>一応リリースされた。</p><p><a href="https://play.google.com/store/apps/details?id=io.github.karino2.paoogo" target="_blank" rel="noopener noreferrer">https://play.google.com/store/apps/details?id=io.github.karino2.paoogo</a></p><p>検討の上の数字がウッテガエシとかでは重なって表示されてしまうな。直さないと。</p><h2 id="検討の数字の修正、リリース、ハイブリッド-2025-10-19-日" tabindex="-1"><a class="header-anchor" href="#検討の数字の修正、リリース、ハイブリッド-2025-10-19-日"><span>検討の数字の修正、リリース、ハイブリッド 2025-10-19 (日)</span></a></h2><p>いくつか来たPRを取り込み、検討の数字の上書きのバグを修正してリリース。</p><h3 id="ハイブリッドの試作" tabindex="-1"><a class="header-anchor" href="#ハイブリッドの試作"><span>ハイブリッドの試作</span></a></h3><p>ぱおぬージュニアは強すぎるがぱおりべは弱すぎる、という事で、この２つの間を作る試み。 ぱおりべは序盤が弱すぎるので、序盤をぱおぬージュニアにして、中盤以降をぱおりべにする、ハイブリッドエンジンを作ってみた。 しばらく打って、14手くらいで切り替えるとちょうど良い強さになりそうなので、これを「ぱおぬり」と呼ぶ事にする。</p><p>しばらく対局してみたが、ちょうどいい弱さだな。よしよし。</p><h2 id="ハイブリッドの調整-2025-10-23-木" tabindex="-1"><a class="header-anchor" href="#ハイブリッドの調整-2025-10-23-木"><span>ハイブリッドの調整 2025-10-23 (木)</span></a></h2><p>ちょうど良い弱さだが、少しぱおぬージュニアとの間が広すぎる気がしたので、少し強い程度に調整したハイブリッドも作る。 まぁこんなもんかなぁ、という感じになったのでひとまずマージ。</p><h2 id="評価値グラフの実装-2025-10-30-木" tabindex="-1"><a class="header-anchor" href="#評価値グラフの実装-2025-10-30-木"><span>評価値グラフの実装 2025-10-30 (木)</span></a></h2><p>評価値グラフを実装しよう。</p><h3 id="グラフライブラリの選定" tabindex="-1"><a class="header-anchor" href="#グラフライブラリの選定"><span>グラフライブラリの選定</span></a></h3><p>低機能でメンテが楽そうな奴を探して、<a href="https://github.com/halfhp/androidplot?tab=readme-ov-file" target="_blank" rel="noopener noreferrer">halfhp/androidplot: Charts and plots for Android</a> にしようかな、と思う。</p><p>とりあえず評価値0.0だけのグラフまで書けた。まぁこれでいこう。</p><h3 id="katagoでの評価値の推移" tabindex="-1"><a class="header-anchor" href="#katagoでの評価値の推移"><span>KataGoでの評価値の推移</span></a></h3><p>1手ずつ出すのはちょっと遅そうなので、まとめて出す方法がほしいな。</p><p>kata-analyzeはmoveを複数渡すと結果を返してくれるっぽいが、非同期でやるにはどうしたらいいのかな。</p><p>コードを眺めていると、main.cppにjsonでのクエリのモードがあって、これと同じ事をやるのが良さそう。 それはanalysis.cppの <code>MainCmds::analysis</code> でやっているっぽい。</p><p>これと同じ感じでやろう。</p><p>JNI側ではスレッドを動かし続けて結果をpollingで取り続ける感じにしよう。 終了もend的なメソッドを呼ぶ。</p><h3 id="評価値グラフが出た-2025-11-06" tabindex="-1"><a class="header-anchor" href="#評価値グラフが出た-2025-11-06"><span>評価値グラフが出た 2025-11-06</span></a></h3><p>なぜかKataGoのスコアが白番目線で、理由がよくわからない。とりあえずマイナスを掛けて表示したらそれっぽいグラフにはなった。 キャンセル用のダイアログがなぜか真っ暗だったり、軸のラベルが多すぎてみづらかったりいまいちな事は多いが、 まずは見た目よりも機能を優先したい。</p><p>とりあえず局面にシンクした表示をしたいな。</p><h3 id="mpandroidchartに乗り換え、局面と対応させる-2025-11-13-木" tabindex="-1"><a class="header-anchor" href="#mpandroidchartに乗り換え、局面と対応させる-2025-11-13-木"><span>MPAndroidChartに乗り換え、局面と対応させる 2025-11-13 (木)</span></a></h3><p>タップ関連の処理がAndroidplotは弱かったのでMPAndroidChartに乗り換え。</p><p><a href="https://github.com/PhilJay/MPAndroidChart?tab=readme-ov-file" target="_blank" rel="noopener noreferrer">PhilJay/MPAndroidChart: A powerful 🚀 Android chart view / graph view library, supporting line- bar- pie- radar- bubble- and candlestick charts as well as scaling, panning and animations.</a></p><p>一応雑にシンク出来るようにはなった。いちいち打った音が鳴るが。</p><p>とりあえずToDoを書き出しておく。</p><ul><li>ハイライトをボタンの移動で追従させる</li><li>グラフが完全に終わったらグラフボタンをdisableにする</li><li>ダイアログがなぜか真っ黒なのを直す</li></ul><h3 id="グラフとのsync周りを修正してリリース-2025-11-14-金" tabindex="-1"><a class="header-anchor" href="#グラフとのsync周りを修正してリリース-2025-11-14-金"><span>グラフとのsync周りを修正してリリース 2025-11-14 (金)</span></a></h3><p>ちょっとゼルダやりすぎて疲れてきたので、息抜きにパオ碁いじり。</p><p>グラフをタップされた時の移動をredoをいっぱい行っていたのをちゃんとジャンプするように変更する。 そしてボタンのナビゲーションで移動した時にグラフのハイライトも移動させるようにする。</p><p>これで割と普通に動く感じにはなったな。後はダイアログが何故か真っ黒なのを直せば一旦リリースしてもいいかな？＞直してリリースした</p><h3 id="やはり9路の布石対応したい-2025-11-19-水" tabindex="-1"><a class="header-anchor" href="#やはり9路の布石対応したい-2025-11-19-水"><span>やはり9路の布石対応したい 2025-11-19 (水)</span></a></h3><p>GnuGoの布石データを見ているとサイズ依存のものを持つ方法が無さそう。9路は中央に直接関わってくるのでこれではダメだよなぁ。 という事で、Kotlinのレイヤーで布石データを持てるようにして、序盤数手はこのデータを使うようにしよう。</p><p>布石のデータはあまりvariationとかを詳しく行うのではなくて、単に厳密一致していたら布石として打ち、外れてたら普通にgenMoveする、という感じにしたい。 布石のデータは序盤の確定の変化だけ、という感じにしたい。 Sabakiで適当に手で作ったSGFを文字列としてハードコードして渡す感じで。assetsにする必要も無いでしょう。</p><p>回転で4つ、さらに鏡像で2つの合計8通りのパターンを生成する感じにする。 各パターンは一つのパターンから生成する感じにしたい。 それぞれの布石オブジェクトが次の手を生成して、その手と相手の手でフィルタリングして行って残ったオブジェクトに毎回次を聞く感じにしたい。 この辺はちょっと型を作ってみないと良くわからないな。</p><p>SGFのreaderはすでにPaooGoには入っているので、割と関数型的に解決出来る問題な気はする。ADTで作るかクラスで作るかはちょっと悩むな。</p><p>variationがない移動、つまりCellのリストが一つの布石とする。それは元となるFusekiDataを8通りに対称移動してできた系列の一つ。 当初は大したサイズにならない予定なので、全リストを最初に持てばいいか。 それを手が一つ進む都度フィルタリングして行って、残ったリストからランダムに選んで次を選ぶことで次の手を決める。 この次の手でまたリストをフィルタリングし、ユーザーが打った手でフィルタリングして、また次の手をランダムで選んで次を選ぶ事で作る。 次がなくなったら布石は終わり。</p><h3 id="_9路用布石を入れてみる-2025-11-19-水" tabindex="-1"><a class="header-anchor" href="#_9路用布石を入れてみる-2025-11-19-水"><span>9路用布石を入れてみる 2025-11-19 (水)</span></a></h3><p>とりあえず振り子で確率的に打つ感じを実装してみた。 いい感じだ。ただ振り子は凄く短いので序盤での調整が難しいな。毎回同じになっちゃう。もう少し長い定石だと序盤を毎回同じにしないと永遠に現れない、となりそうなので、調整が悩ましいなぁ。</p><p>布石のデータはハードコードした文字列で渡すが、文字列はSGFなので、Sabakiでsgfを作って追加していく感じになる。</p><p>ブラックブーメランと豆まきのsgfは作った。あとは王道進行で風車、リフティング、扇子を入れたらとりあえずはいいかな。</p><p>ちなみに振り子、一間飛びまで打たれるとgnugo 2.6になかなか勝てない。普段は序盤のしょぼさで勝ってたんだなぁ。</p><p>しばらく電車で打ってみたが凄くいい感じだったので、もう少し布石を足す。一応、天元、星、高目の三つの布石は揃えた。 布石を使ってくる奴は別人という事でgnugo2系列+布石はぱおふせという名前のエンジンという事にした。 ぱおぬーパパとぱおぬー爺はgnugo 3系列の布石あり（採用頻度の違い。ぱおふせジュニアも同様）</p><p>しばらくやってみたが、かなり遊べるようになった。ぱおふせジュニアが当面のライバル。</p><h3 id="sgf保存をとりあえず動くまで-2025-11-21-金" tabindex="-1"><a class="header-anchor" href="#sgf保存をとりあえず動くまで-2025-11-21-金"><span>SGF保存をとりあえず動くまで 2025-11-21 (金)</span></a></h3><p>gobandroidにあった保存ダイアログを少し手直ししてSAFとして保存するようにしてみたが、ファイル名に日付を追加したりする仕様が微妙に面倒なので、 デフォルトでよくある名前を入れておいてあとはユーザーが勝手に手で編集してね、でいい気がする。</p><p>ちょっとその辺手直ししよう。</p><p>手直ししてみた。保存はまぁこれでいいかな、という感じにはなった。現状は終了しないと保存出来ないが、ゲーム中とかreview中でも保存出来ていいよな。</p><p>あとは共有と開くを実装したら次のバージョン公開かなぁ。</p><h3 id="sgfを開く、つぶや棋譜2で共有、クリップボードにコピー-2025-11-23-日" tabindex="-1"><a class="header-anchor" href="#sgfを開く、つぶや棋譜2で共有、クリップボードにコピー-2025-11-23-日"><span>SGFを開く、つぶや棋譜2で共有、クリップボードにコピー 2025-11-23 (日)</span></a></h3><p>ちょっと暇だったのでSGFを開く、も実装してみる。単にReviewに渡していて外から開く場合と必要な情報はちょっと違うよなぁ、とか思うが、そういう対応はまだしてない。</p><p>とりあえず共有も動くようにして、ゲームの途中でも保存出来るようにしたらひとまず公開して、おいおい色々直していこう。</p><p>つぶや棋譜2のurlを生成してACTION_SENDを送るようにした。SGFのurl encodeは長いが、まぁ9路なら動いてそうだしいいか。</p><p>クリップボードにコピーも一応実装しておく。 ついでに振り子があんま出なくなっていたので王道進行と同じ比率にする（変化が多い布石が選ばれやすかったのを修正）。</p><p>あとは設定画面を作ればリリースできそうだが、今日のところはこのくらいにしておいてやる。</p><h3 id="setttings画面を追加してp0-7リリース-2025-11-24-月" tabindex="-1"><a class="header-anchor" href="#setttings画面を追加してp0-7リリース-2025-11-24-月"><span>Setttings画面を追加してp0.7リリース 2025-11-24 (月)</span></a></h3><p>とりあえずリリースしてしまいたかったので、設定画面を作ってリリース。</p><h3 id="ぱおりばパパの追加、解析の結果のキャッシュと自動適用、他-2025-12-04-木" tabindex="-1"><a class="header-anchor" href="#ぱおりばパパの追加、解析の結果のキャッシュと自動適用、他-2025-12-04-木"><span>ぱおりばパパの追加、解析の結果のキャッシュと自動適用、他 2025-12-04 (木)</span></a></h3><p>木曜のAndroidもくもく会なので何か直そうと思ったが、割とパオ碁は完成されている事に気づく。 とりあえずヒントがundoとかでクリアされてないのを修正し、libertyに布石を追加したぱおりばパパを追加する。</p><p>ただ作ってみるとぱおりばパパは弱すぎるな。布石+libertyは弱すぎるが布石+gnugo 2.6は強すぎる。</p><p>ついでに解析結果をキャッシュして、移動のつどその局面のキャッシュがあるかをチェックするようにした。 これでだいぶ解析がはかどるな。</p>`,250)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};